var _docksVivas = [];
/* Fechou gaveta? A dock volta na hora, sem depender de rolagem. */
function acordarDocks(){ _docksVivas.forEach(function(f){ try { f(); } catch(e) {} }); }
/* ─── Dock da zona do polegar (comportamento padrão) ───
   iniciarDock('idDaDock', { protegidaPor: 'idDeGavetaQueImpedeRecolher' }) */
function iniciarDock(dockId, opts) {
  opts = opts || {};
  var dock = document.getElementById(dockId);
  if (!dock) return;
  document.body.classList.add('temDock');
  var timer = null, lastY = 0;
  // Informa a altura real da dock ao CSS, para as gavetas reservarem a folga certa
  function medirDock(){
    var h = dock.offsetHeight || 160;
    document.documentElement.style.setProperty('--alturaDock', h + 'px');
  }
  medirDock();
  window.addEventListener('resize', medirDock);
  if (window.ResizeObserver) { try { new ResizeObserver(medirDock).observe(dock); } catch(e) {} }
  function protegida() {
    // Nunca recolher com gaveta aberta, com o dedo na dock ou com campo em foco
    if (dock.dataset.segurando === '1') return true;
    if (dock.contains(document.activeElement)) return true;
    var alvos = [].concat(opts.protegidaPor || []);
    for (var i = 0; i < alvos.length; i++) {
      var g = document.getElementById(alvos[i]);
      if (g && g.classList.contains('open')) return true;
    }
    return false;
  }
  function agendar() {
    if (timer) clearTimeout(timer);
    timer = setTimeout(function(){
      if (protegida()) { agendar(); return; }
      dock.classList.add('recolhida');
    }, 8000);
  }
  function mostrar() { dock.dataset.segurando = '0'; dock.classList.remove('recolhida'); agendar(); }
  window['mostrarDock_' + dockId] = mostrar;
  _docksVivas.push(mostrar);
  /* Soltar o dedo em QUALQUER lugar limpa a marca (antes ela ficava presa
     quando o toque come\u00e7ava na dock e terminava sobre uma gaveta) */
  ['pointerup','touchend','touchcancel','mouseup'].forEach(function(ev){
    document.addEventListener(ev, function(){ dock.dataset.segurando = '0'; });
  });
  window['mostrarDock_' + dockId] = mostrar;
  window.addEventListener('scroll', function(){
    var y = window.scrollY;
    if (y < 24) { mostrar(); }
    else if (y > lastY + 4 && !protegida()) { dock.classList.add('recolhida'); if (timer) clearTimeout(timer); }
    else if (y < lastY - 4) { mostrar(); }
    lastY = y;
  }, { passive:true });
  // Enquanto o dedo estiver na dock, ela não foge
  ['touchstart','pointerdown','mousedown'].forEach(function(ev){
    dock.addEventListener(ev, function(){ dock.dataset.segurando = '1'; mostrar(); });
  });
  ['touchend','pointerup','mouseup','touchcancel'].forEach(function(ev){
    dock.addEventListener(ev, function(){ dock.dataset.segurando = '0'; mostrar(); });
  });
  ['click','focusin','input','change'].forEach(function(ev){
    dock.addEventListener(ev, function(){ mostrar(); });
  });
  mostrar();
}


/* ===================================================================
   v6-18 · MINI-PLAYER DO REDACAST (acima do dock, em todas as telas)
   Estado em localStorage 'redaon-cast': { id, url, tit, t, dur, tocando, rate }
   A Você ON grava o estado; aqui ele é retomado. O Escrever marca tocando=false.
   =================================================================== */
(function(){
  var CHAVE = 'redaon-cast';
  function ler(){ try{ return JSON.parse(localStorage.getItem(CHAVE) || 'null'); }catch(e){ return null; } }
  function gravar(o){ try{ localStorage.setItem(CHAVE, JSON.stringify(o)); }catch(e){} }
  function limpar(){ try{ localStorage.removeItem(CHAVE); }catch(e){} }
  window.redaCastEstado = { ler:ler, gravar:gravar, limpar:limpar };
  if (/voce-on\.html/.test(location.pathname)) return;

  var ICO_PLAY = '<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';
  var ICO_PAUSA = '<svg viewBox="0 0 24 24"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>';
  var st = null, a = null, el = null, ultimo = 0;

  function css(){
    if (document.getElementById('castMiniCss')) return;
    var e = document.createElement('style'); e.id = 'castMiniCss';
    e.textContent =
      '#castMini{ position:fixed; left:12px; right:12px; bottom:calc(92px + env(safe-area-inset-bottom)); z-index:43; display:flex; align-items:center; gap:10px;'
      + ' background:var(--surface); border:1px solid rgba(var(--borderRGB),.2); border-radius:16px; padding:10px 10px 8px; box-shadow:0 4px 16px rgba(0,0,0,.18); color:var(--text); max-width:560px; margin:0 auto; cursor:pointer; }'
      + '#castMini .prog{ position:absolute; left:14px; right:14px; top:3px; height:3px; border-radius:2px; background:rgba(var(--borderRGB),.25); overflow:hidden; }'
      + '#castMini .prog i{ display:block; height:100%; width:0; background:var(--cyan); }'
      + '#castMini img{ width:40px; height:40px; flex:none; border-radius:50%; background:#fdfbf4; object-fit:contain; padding:2px; }'
      + '#castMini .tx{ flex:1; min-width:0; }'
      + '#castMini .tx b{ display:block; font-size:13px; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }'
      + '#castMini .tx span{ display:block; font-size:11.5px; color:var(--muted); }'
      + '#castMini .pp{ width:38px; height:38px; flex:none; border-radius:50%; border:0; background:var(--cyan); color:var(--onCyan); display:grid; place-items:center; cursor:pointer; }'
      + '#castMini .pp svg{ width:17px; height:17px; fill:currentColor; }'
      + '#castMini .x{ flex:none; background:transparent; border:0; color:var(--muted); font-size:20px; line-height:1; padding:6px; cursor:pointer; font-family:inherit; }'
      + 'body.comCast #conteudo{ padding-bottom:170px; }'
      + '@media(min-width:1024px){ #castMini{ left:auto; right:24px; bottom:24px; width:380px; margin:0; } body.comCast #conteudo{ padding-bottom:110px; } }';
    document.head.appendChild(e);
  }
  function fmt(t){ t = Math.max(0, Math.floor(t || 0)); return Math.floor(t/60) + ':' + String(t%60).padStart(2,'0'); }
  function salvar(){ if (!st || !a) return; st.t = a.currentTime || st.t || 0; st.dur = a.duration || st.dur || 0; st.tocando = !a.paused; gravar(st); }
  function pintar(){
    if (!el) return;
    el.querySelector('.pp').innerHTML = a.paused ? ICO_PLAY : ICO_PAUSA;
    var d = a.duration || st.dur || 0, c = a.currentTime || st.t || 0;
    el.querySelector('.prog i').style.width = (d ? Math.min(100, c/d*100) : 0) + '%';
    el.querySelector('.tx span').textContent = 'RedaCast \u00b7 ' + fmt(c);
  }
  function montar(){
    css();
    el = document.createElement('div'); el.id = 'castMini'; el.setAttribute('role','button');
    el.innerHTML = '<span class="prog"><i></i></span><img src="avatares/redacast-selo.webp?v=23" alt=""><div class="tx"><b></b><span></span></div>'
      + '<button class="pp" aria-label="Tocar ou pausar"></button><button class="x" aria-label="Parar">&times;</button>';
    el.querySelector('.tx b').textContent = st.tit || 'RedaCast';
    document.body.appendChild(el); document.body.classList.add('comCast');
    el.addEventListener('click', function(ev){
      if (ev.target.closest('.pp')){ if (a.paused) a.play().catch(function(){}); else a.pause(); return; }
      if (ev.target.closest('.x')){ a.pause(); limpar(); el.remove(); document.body.classList.remove('comCast'); st = null; return; }
      salvar(); location.href = 'voce-on.html?ep=' + encodeURIComponent(st.id) + '&abrir=1';
    });
    a = new Audio(); a.preload = 'auto'; a.src = st.url;
    a.addEventListener('loadedmetadata', function(){ if (st.t && st.t < a.duration - 3) a.currentTime = st.t; if (st.rate) a.playbackRate = st.rate; pintar(); });
    ['play','pause','ended'].forEach(function(ev){ a.addEventListener(ev, function(){ salvar(); pintar(); }); });
    a.addEventListener('timeupdate', function(){ pintar(); var n = Date.now(); if (n - ultimo > 3000){ ultimo = n; salvar(); } });
    a.addEventListener('ended', function(){ limpar(); if (el){ el.remove(); document.body.classList.remove('comCast'); } });
    window.addEventListener('pagehide', salvar);
    if ('mediaSession' in navigator){ try{
      navigator.mediaSession.metadata = new MediaMetadata({ title: st.tit || 'RedaCast', artist:'RedaCast \u00b7 RedaON' });
      navigator.mediaSession.setActionHandler('play', function(){ a.play(); });
      navigator.mediaSession.setActionHandler('pause', function(){ a.pause(); });
      navigator.mediaSession.setActionHandler('seekbackward', function(){ a.currentTime = Math.max(0, a.currentTime - 10); });
      navigator.mediaSession.setActionHandler('seekforward', function(){ a.currentTime = Math.min((a.duration||0) - 0.5, a.currentTime + 10); });
    }catch(x){} }
    pintar();
    if (st.tocando){ var pr = a.play(); if (pr && pr.catch) pr.catch(function(){ st.tocando = false; pintar(); }); }
  }
  function iniciar(){ st = ler(); if (!st || !st.url || !st.id) return; montar(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniciar); else iniciar();
})();


/* ─── Ciclo do aluno (v6-21 · Fatia A) ─────────────────────────────────────
   O ciclo gira em torno do dia da redação da turma (turmas.dia_redacao, 1=seg … 7=dom;
   vazio = segunda). Começa dois dias úteis antes da redação e dura 7 dias.
   Dia de descanso = o que o aluno marca no Meu Plano (plano_config.descanso); nele não
   há planejamento. O dia da turma nunca é descanso.
   O tema do ciclo é o tema da semana que vale no primeiro dia do ciclo e segue até o fim.
   A chave do ciclo (plano_itens.semana_de) é a data da redação. */
function cicloISO(d){ return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); }
function cicloDiaSemana(d){ var n = d.getDay(); return n === 0 ? 7 : n; }
function cicloFolgas(descanso){
  if (descanso === 'sab') return [6];
  if (descanso === 'dom') return [7];
  if (descanso === 'nenhum') return [];
  return [6,7];
}
function cicloCalcular(diaRedacao, descanso, hoje){
  var diaRed = (diaRedacao >= 1 && diaRedacao <= 7) ? diaRedacao : 1;
  var folgas = cicloFolgas(descanso);
  var h = hoje ? new Date(hoje) : new Date(); h.setHours(0,0,0,0);
  function soma(d, n){ var x = new Date(d); x.setDate(x.getDate() + n); return x; }
  function util(d){ var w = cicloDiaSemana(d); return w === diaRed || folgas.indexOf(w) === -1; }
  function inicioDe(red){ var x = new Date(red), n = 0; while (n < 2){ x = soma(x, -1); if (util(x)) n++; } return x; }
  var red = null;
  for (var i = -14; i <= 14; i++){
    var d = soma(h, i);
    if (cicloDiaSemana(d) !== diaRed) continue;
    if (inicioDe(d) <= h) red = d;
  }
  var ini = inicioDe(red), dias = [];
  for (var k = 0; k < 7; k++) dias.push(soma(ini, k));
  return { diaRedacao: diaRed, folgas: folgas, redacao: red, inicio: ini, fim: dias[6], dias: dias,
           chave: cicloISO(red), util: util, hoje: h };
}
var _cicloPromessa = null;
function cicloDoAluno(opc){
  if (_cicloPromessa && !(opc && opc.recarregar)) return _cicloPromessa;
  _cicloPromessa = (async function(){
    var uid = (typeof authGetUserId === 'function') ? authGetUserId() : null;
    var diaRed = null, descanso = 'sab', tema = null;
    if (uid && typeof dbFetch === 'function' && typeof SUPABASE_URL !== 'undefined'){
      try{
        var rt = await dbFetch(SUPABASE_URL + '/rest/v1/alunos_turma?aluno_id=eq.' + uid + '&status=eq.ativo&select=turmas(dia_redacao)&order=entrou_em.desc&limit=1', {});
        if (rt.ok){ var t = await rt.json(); if (t[0] && t[0].turmas) diaRed = t[0].turmas.dia_redacao; }
      }catch(e){}
      try{
        var rc = await dbFetch(SUPABASE_URL + '/rest/v1/plano_config?aluno_id=eq.' + uid + '&select=descanso', {});
        if (rc.ok){ var c = await rc.json(); if (c[0] && c[0].descanso) descanso = c[0].descanso; }
      }catch(e){}
    }
    var ciclo = cicloCalcular(diaRed, descanso);
    ciclo.descanso = descanso;
    if (typeof dbFetch === 'function' && typeof SUPABASE_URL !== 'undefined'){
      try{
        var r = await dbFetch(SUPABASE_URL + '/rest/v1/temas?select=id,titulo,semana_de,capa_url,campo&ativo=eq.true&semana_de=lte.' + cicloISO(ciclo.inicio) + '&order=semana_de.desc&limit=1', {});
        if (r.ok){ var ts = await r.json(); tema = ts[0] || null; }
      }catch(e){}
    }
    ciclo.tema = tema;
    return ciclo;
  })();
  return _cicloPromessa;
}
